        "id": "cauliflower_cheddar_biscuits",
        "title": "Cauliflower Cheddar Biscuits",
        "description": "Makes 4 servings:",
        "ingredients": [
            "3 greens \u2022 1 leaner protein\u2022 1.5 condiments",
            "4 cups (13.6 oz) cauliflower, cut into florets (8 greens)",
            "2 cups (6.2 oz) broccoli, cut into florets (4 greens)",
            "1 1/2 cup (6 oz) low fat cheddar cheese, grated (1 leaner protein)",
            "12 oz non-fat greek yogurt (1 leanest protein)",
            "4 eggs & 8 egg whites (2 leaner protein)",
            "3 tablespoons water",
            "3/4 teaspoon salt (3 condiments)",
            "1/2 teaspoon onion powder (1 condiment)",
            "1/2 teaspoon garlic powder (1 condiment)",
            "\u00bd teaspoon of freshly ground pepper (1 condiment)"
        ],
        "directions": [
            "1. Preheat oven to 400\u00ba F lightly grease 1-2 (mini) muffin tin(s) with non-stick spray.",
            "2. Working in batches, place cauliflower and broccoli florets in food processor and pulse until it resembles grains of rice.",
            "3. Place grated vegetables in a large, microwaveable dish, along with 3 tablespoons water, cover with a damp paper towel and microwave for 5 minutes, or until cauliflower is tender.",
            "4. Carefully remove steamed cauliflower and transfer to a clean kitchen towel. Wrap up the cauliflower and wring out all excess moisture into the sink.",
            "5. Repeat until all liquid has been drained.",
            "6. Transfer cauliflower and broccoli to a large bowl and mix in cheddar cheese, Greek yogurt and eggs, then season with salt, onion and garlic powder, and pepper.",
            "7. In a separate bowl, beat egg whites until stiff peaks form, then gradually fold egg whites into cauliflower mixture. Don\u2019t over mix.",
            "8. Spoon batter into muffin tins, then place muffin tins in oven and bake for 25-30 minutes, or until tops are golden brown."
        ],
