            "1 tbsp sesame oil",
            "2 egg whites",
            "1 large egg",
            "pinch of salt",
            "cooking spray",
            "1/2 small onion, diced fine",
            "1/2 cup frozen peas and carrots",
            "2 garlic cloves, minced",
            "5 scallions, diced, whites and greens separated",
            "3 tbsp soy sauce, or more to taste (Tamari for Gluten Free)"
