        "title": "Cauliflower, Coconut oil, Ginger, Turmeric Stew \u2013 Amazing!",
        "description": "This delicious stew is perfect for vegetarians or meat eaters. And it\u2019s full of healthy fats! Comforting and warm, it\u2019s one the whole\u00a0family can enjoy for dinner. Add in some chicken or tofu for extra protein. If you\u2019re enjoying a bit of grains, this pairs nicely with wild rice. \u00a0\u00a0Click here to view the PDF version.",
