        "description": "Want an easy recipe for cooking salmon? \u00a0Try this cilantro lime honey garlic salmon baked in foil. Healthy, gluten free recipe that takes only 30 minutes from start to finish .\nCourse Main Course\nCuisine American\nKeyword baked salmon, cilantro lime salmon\nPrep Time 10\nminutes\nminutes\nCook Time 20\nminutes\nminutes\nTotal Time 30\nminutes\nminutes\nServings 2 servings\nCalories 456kcal\nAuthor Julia",
