            "Lightly flatten each cookie with the back of a fork or spatula.",
            "Step 6: Bake Until Golden",
            "Bake at 350\u00b0F (175\u00b0C) for 15\u201318 minutes , or until the edges are lightly golden and set.",
            "Let cool on the baking sheet for 5 minutes , then transfer to a wire rack to finish cooling.",
            "Cookies firm up as they cool\u2014this helps them hold their shape."
