        "description": "This creamy orzo pasta is packed with veggies (roasted butternut squash, spinach, and garlic)! The recipe takes only 30 minutes and is perfect for busy family weeknights when you're craving comfort foodon a cold\u00a0Fall or Winter\u00a0night. Serve this cozy meal as a meatless main course or as a side dish alongside your favorite proteins (chicken, beef, pork, seafood).\nCourse Main Course\nCuisine American, Italian\nKeyword orzo pasta\nPrep Time 5 minutes\nCook Time 25 minutes\nTotal Time 30 minutes\nServings 5 people\nCalories 411kcal\nAuthor Julia",
