            "1 red bell pepper, diced",
            "1 cup carrots, julienned",
            "1 (11 oz.) can mandarin oranges, drained and patted dry",
            "\u00bd cup green onions, chopped",
            "\u00bc cup cilantro, roughly chopped",
            "\u00bd cup honey-roasted peanuts",
