            "1 small onion diced",
            "3 medium carrots peeled and thinly diced",
            "2 small celery stalks chopped",
            "\u00bd teaspoon garlic powder",
            "\u00bd teaspoon onion powder",
            "4 cloves garlic minced",
            "7 cups chicken stock or broth",
            "1 teaspoon fresh thyme",
