            "2 tablespoons olive oil",
            "1 lb skinless boneless chicken thighs or breasts",
            "\u00bd teaspoon smoked paprika",
            "\u00bd teaspoon dried oregano",
            "\u00bc teaspoon salt",
            "\u00bc teaspoon black pepper",
            "Veggies",
