        "description": "Print\nPrep time 20 mins\nCook time 1 hour\nTotal time 1 hour 20 mins\nTaste the flavors of the season in this quiche recipe that is filled with roasted butternut squash, kale and gruyere cheese.\nServes: 4-6 servings as a main dish",
