        "id": "strawberry_mango_salad",
        "title": "Strawberry Mango Salad",
        "description": "Strawberry Mango Salad is a healthy and refreshing 15-minute Summer salad that a whole family will love! Vibrant and colorful, it makes a perfect light lunch or a stunning side for your dinner. It pairs well with grilled meats (chicken, steak, and pork) and seafood. Bring it to potlucks, picnics, BBQs, and parties to share with family and friends.\nCourse Salad\nCuisine American, Mediterranean\nKeyword mango salad, strawberry mango salad\nPrep Time 15\nminutes\nminutes\nTotal Time 15\nminutes\nminutes\nServings 6 people\nCalories 231kcal\nAuthor Julia",
