        "id": "tiktok_cinnamon_rolls",
        "title": "Tiktok Cinnamon Rolls",
        "description": "PREP TIME: 30 minutes\nCOOK TIME: 20 minutes\nRISING TIME: 1 hour 30 minutes\nTOTAL TIME: 3 hours\nSERVINGS: 12 giant cinnamon rolls",
        "ingredients": [
            "Cinnamon Roll Dough",
            "2 cups (472g) milk",
            "1/2 cup (111g) salted butter, cold",
            "2 tbsp dry, active yeast",
            "1/2 cup (118g) warm water",
            "1/4 cup (58g) + 1/2 tsp granulated sugar, divided",
            "1 tbsp salt",
            "3 eggs",
            "6 -7 cups (912-1064g) all-purpose flour",
            "Cinnamon Roll Filling",
            "4 tbsp salted butter, melted",
            "1 1/2 cups (369g) brown sugar, packed",
            "2 tsp cinnamon",
            "3/4 cup (180g) heavy whipping cream",
            "Vanilla Buttercream Icing",
            "1/2 cup (111g) salted butter, room temperature",
            "3 cups (321g) powdered sugar",
            "2 tsp vanilla, I like to use clear vanilla",
            "1/4- 1/2 cup (60-120mL) heavy cream"
        ],
        "directions": [
            "Scald the milk in the microwave until almost boiling. (Usually about 1-2 mintues.)",
            "Place the cold stick of butter into the hot milk. Let the butter melt and then stir. Cool until almost room temperature.",
            "Mix the warm water, yeast and 1/2 tsp of sugar together. Let the yeast activate while the milk is cooling. The yeast will get very bubbly, this means the yeast is alive.",
            "Pour the room temperature milk and the yeast mixture into the bowl of a stand mixer.",
            "Add in 3 cups of flour and briefly mix together.",
            "Add in the remaining 1/4 cup sugar, salt and eggs. Mix until well combined.",
            "Add 3 more cups of flour and slowly mix until combined. Slowly add in the last cup of flour. This dough will be very tacky.",
            "Cover with plastic wrap and let the dough rise for 1 hour or until double.",
            "Pour the dough out onto a floured surface and gently roll into a large rectangle. Approx 12 inch by 24 inches.",
            "Brush the dough with melted butter and then sprinkle brown sugar and cinnamon on top. Make sure to leave an inch strip at the top completely bare. You will use this to seal the roll together so they don\u2019t unwind while baking.",
            "Use a rolling pin and press the filling into the dough.",
            "Use a pizza cutter and cut the dough into 12 two inch strips. Roll up each strip and place in a greased 9\u00d713 pan.",
            "Warm the heavy cream in the microwave for 30-45 seconds. Slowly pour over each cinnamon roll.",
            "Cover the pan with plastic wrap and let the cinnamon rolls rise for an additional 30 minutes.",
            "Turn the oven on to 375\u00b0 F while the rolls are finishing their second rise.",
            "Bake at 375\u00b0 for 15-20 minutes or until golden brown.",
            "**To make the Vanilla Buttercream Icing, Cream the butter until smooth.**",
            "Alternate adding the rest of the frosting ingredients, one cup of powdered sugar and then some liquid until all of the ingredients are added. Add the liquid slowly until you achieve your desired consistency.",
            "Mix on low until smooth and creamy.",
            "Frost the still warm cinnamon rolls + enjoy!"
        ],
