        "title": "Tomato Spinach Chicken Spaghetti",
        "description": "This chicken pasta recipe has lots of fresh ingredients: garlic, tomatoes, and spinach.\u00a0 \u00a0This easy and quick dinner will become a family favorite!\nCourse Main Course\nCuisine Italian, Mediterranean\nKeyword tomato chicken pasta, tomato spinach chicken pasta, tomato spinach pasta\nPrep Time 10 minutes\nCook Time 20 minutes\nTotal Time 30 minutes\nServings 4 servings\nCalories 532kcal\nAuthor Julia",
