            "cashew cream",
            "1\u00bd cups raw cashews*(see note)",
            "1 cup fresh water",
            "1 garlic clove",
            "3\u00bd tablespoons fresh lemon juice",
            "sea salt and freshly ground pepper",
            "**filling**",
            "4 cups fresh baby spinach",
            "1 cup crumbled firm tofu",
            "1 teaspoon dried oregano",
