            "Assemble the shells. Spread \u00bc cup of the reserved cashew cream on the bottom of an 11x7-inch baking dish. Fill each shell with some of the filling and a few cubes of butternut squash, and place into the baking dish. Drizzle a little olive oil over the shells and bake for 15 minutes, or until browned on top and heated through. Remove from the oven and serve with the remaining cashew cream."
