            "1 Tbsp Rice Vinegar",
            "1 Tbsp Hoisin Sauce",
            "2 tsp Coconut Sugar",
            "1 tsp Toasted Sesame Oil",
            "\u00bd tsp Chili Flakes Red Pepper Flakes",
            "**Lo Mein:**",
            "2 Tbsp Sesame Oil",
            "3 Cloves Garlic Crushed",
            "1 Tbsp Fresh Ginger Finely Grated",
            "2 cups Shiitake Mushrooms (150g) Sliced, Stems Removed",
            "\u00bd cup Spring Onions (50g) Sliced, White and Green Parts Separated",
            "1 Medium Red Bell Pepper Sliced",
            "1 Large Carrot Julienned or Sliced",
            "1 cup Baby Corn (130g)",
            "3 cups Baby Spinach (90g)",
            "**Serving:**",
