            "2 cloves garlic, minced",
            "3 tablespoons olive oil",
            "4 eggs",
            "1/2 cup light mayonnaise",
            "4 ounces Pecorino-Romano cheese, grated (1 cup)",
            "8 ounces shredded mozzarella cheese (2 cups)",
            "12 rich round crackers, crushed (about 2/3 cup)"
